\99\165\80\71\77\168\93\5","\201\49\36\36"),v7("\55\32\165\103\68\39\185\48\14\59\185\100\68\56\175\98\29\110\172\113\23\58\234\103\1\47\190\120\1\60\235\48\45\110\184\117\5\42\234\100\12\47\190\49\68\7\234\125\5\42\175\48\16\38\171\100\68\59\186\49","\16\100\78\202"),"I'm not old! That's— nobody said old! Sorry! Nevermind!"},[v7("\137\147\95\216\188\96\106\152\142\149\85","\203\221\220\16\150\227\34\43")]={v7("\204\37\114\108\186\100\53\54\181\6\122\107\232\45\126\56\252\43\111\56\246\61\59\118\250\41\126\56\233\45\124\112\239\101\59\65\244\49\59\127\244\48\59\117\226\100\117\121\246\33\59\106\242\35\115\108\186","\24\155\68\27"),"We're for sure friends! Of course! Just us Mains! Hahaha!",v7("\152\81\195\65\179\85\144\91\169\16\209\18\188\89\195\90\251\16\246\91\169\88\144\83\168\85\144\93\182\84\213\64\250\68\216\83\180\16\196\64\191\85\195\19\250\121\144\81\178\85\211\89\191\84\145\18\142\71\217\81\191\17","\50\218\48\176"),v7("\103\18\220\241\77\81\14\92\209\230\94\70\14\80\209\245\85\20\90\93\148\228\83\81\14\93\215\245\90\90\15\18\253\176\83\85\88\87\148\242\94\81\64\18\192\255\27\85\14\86\221\247\27\71\71\70\209\177\27\103\71\95\221\252\90\70\14\86\193\227\79\21","\52\46\50\180\144\59"),v7("\43\56\54\127\70\49\251\27\52\101\117\3\60\244\77\48\55\120\19\55\254\77\55\42\101\3\47\255\31\112\101\68\14\54\237\64\62\35\113\21\120\186\58\62\43\115\3\43\252\24\61\100","\154\109\81\69\23\102\89"),v7("\211\205\156\118\64\42\233\194\217\20\86\56\244\223\207\20\85\54\186\195\217\85\83\121\251\201\211\65\85\121\238\195\217\20\101\60\236\196\210\93\64\55\182\139\245\20\73\56\236\206\156\85\1\45\251\199\215\21\1\9\232\206\204\85\83\60\254\138\156\114\78\43\247\202\200\64\68\61\187","\89\154\171\188\52\33"),"Bassie has scales, I have a shell! We're both wearing the correct outfit!","I almost said something and then didn't! That's normal! That's a normal thing I do!"},[v7("\197\36\62\31\216\32\51\25\216","\86\150\116\108")]={"Sprinting! Or— whatever that was! It was fast! I noticed the fast!","Ooo, speed! I'm not built for speed! I'm built for gently holding small bones!","Go! Go! I'll keep up! I won't keep up! But I'll keep going!","That's the fast one! I remember the fast one! I've read about velocity!","Careful on the corners! Actually— don't be careful! Be fast! Sorry!","You're so quick! I'm the slow one of the team and I've made peace with it!","Fast fast fast! That's the whole sentence! I panicked!",v7("\69\170\34\238\205\79\124\186\108\175\129\97\118\179\32\167\204\79\122\170\63\239\129\114\127\186\53\238\214\67\101\186\108\172\212\79\123\171\108\168\206\84\55\182\56\239\129\127\120\170\108\162\206\73\124\255\46\187\200\74\99\255\42\161\211\6\126\171\109","\38\23\223\76\206\161"),"If you get too far ahead I'll just— narrate! From back here! Cheerfully!","Speed without stamina! That's the dream! That's actually my dream!","I'm impressed and slightly dizzy! Mostly impressed!"},[v7("\235\249\106\18\141\158\249\247\239\126","\166\184\169\56\91\195\202")]={"Slower now? Good! I mean— not good! Just easier to keep up with!",v7("\133\177\114\47\130\179\191\49\42\205\181\189\112\40\130\176\177\125\47\203\169\183\48\100\236\168\162\124\37\206\231\185\98\100\207\190\240\119\37\212\168\165\99\45\214\162\240\98\52\199\162\180\48\100\236\168\240\126\34\196\162\190\114\33\130\179\191\49\34\195\180\164\48","\162\199\208\17\68"),v7("\254\237\94\24\173\78\99\23\222\241\86\15\235\78\84\20\198\232\30\65\193\23\16\23\212\225\76\65\255\15\73\91\197\238\94\15\231\78\73\20\196\167\31\40\172\29\81\2\145\242\87\0\226\5\16\2\222\243\30","\123\177\134\63\97\140\110\48"),v7("\9\91\225\131\225\15\122\249\32\81\240\130\178\60\103\236\49\64\181\131\220\20\97\169\55\70\241\194\230\90\53\199\53\65\224\209\243\23\52\169\7\85\231\131\230\19\116\253\112\85\180\193\243\31\53\250\36\91\228\156","\137\80\52\148\163\146\123\21"),"Walking! Remember walking? We're doing that again! Lovely!","I'll catch my breath with you! Team breathing! Is that a thing? It's a thing now!",v7("\203\204\172\233\6\234\128\174\251\2\246\211\227\243\12\234\197\227\234\10\245\197\227\234\12\184\204\172\241\8\184\193\183\190\23\240\201\173\249\16\185\128\133\241\16\235\201\175\237\67\249\210\166\190\14\247\211\183\242\26\184\204\172\241\8\241\206\164\191","\99\152\160\195\158"),"That's fine! Fast is a sometimes food! Walking is the meal!","No more sprint! I'll stop narrating the wind! It was getting weird!",v7("\174\119\218\55\22\58\131\119\194\54\24\127\129\54\197\42\93\47\134\37\194\127\93\22\199\54\218\45\18\127\139\62\221\59\93\43\143\62\197\126\13\62\149\35\151\126\52\127\139\62\221\59\93\50\136\36\194\126\13\62\149\35\197\114\93\55\136\57\211\45\9\51\158\118","\95\231\87\182\94\125")},[v7("\107\226\209\24\37","\115\56\169\152\84\105\28")]={"PERFECT! Did you see that? I saw that! I'm writing it down!",v7("\10\237\128\91\246\82\63\246\193\78\246\66\44\224\128\91\247\5\31\165\147\74\183\73\126\226\147\74\183\81\127\165\168\15\190\64\63\247\133\15\162\77\59\165\146\64\163\75\58\164\193\123\190\64\126\226\142\64\178\5\45\234\148\65\178\4","\37\94\133\225\47\214"),v7("\121\221\85\91\23\220\87\80\83\199\23\30\126\148\85\81\66\216\82\30\89\209\64\91\69\149\22\115\78\148\94\95\89\208\69\30\86\198\83\30\81\219\68\30\71\219\95\80\67\221\88\89\23\213\66\30\69\219\85\85\68\149","\62\55\180\54"),"That's the timing of a naturalist! Precise! Steady! I'm taking notes!","Right in the middle! That's where the good zone lives! You found it!",v7("\220\232\45\199\86\5\238\60\233\255\41\210\3\4\135\91\240\255\45\214\2\87\175\2\242\244\47\134\69\86\171\26\239\187\104\239\86\4\185\26\232\186\47\212\71\69\186\91\239\242\39\211\69\76\239","\123\155\154\72\166\34\36\206"),"You made that look intentional! Was it? Doesn't matter! Great!",v7("\245\212\49\175\41\135\159\25\160\49\211\222\52\227\54\205\214\52\175\100\134\241\55\183\101\202\202\59\168\100\134\242\55\176\49\202\198\120\173\42\210\159\52\182\38\205\158\120\132\55\195\222\44\226","\69\166\191\88\195"),v7("\150\117\33\3